export const BACKUP_COMMANDS=Object.freeze(['backup.plan','backup.preview','backup.stage','backup.drill','backup.activationRequest']);

const safe=value=>String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const STYLE=`
.s18-backup{display:grid;gap:14px;min-width:0}.s18-backup__banner{border:1px solid var(--border,#2b3441);border-radius:12px;padding:14px;background:var(--panel,#111821)}.s18-backup__banner h2{margin:0 0 6px;font-size:18px}.s18-backup__banner p{margin:5px 0;color:var(--muted,#9ba7b8);line-height:1.5}.s18-backup__flow{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:9px}.s18-backup__step{border:1px solid var(--border,#2b3441);border-radius:11px;padding:11px;background:#0e151e;min-width:0}.s18-backup__step h3{margin:0 0 5px;font-size:13px}.s18-backup__step p{margin:0;color:var(--muted,#9ba7b8);font-size:11px;overflow-wrap:anywhere}.s18-backup__work{display:grid;grid-template-columns:minmax(220px,.35fr) minmax(0,1fr) minmax(230px,.38fr);gap:12px}.s18-backup__card{border:1px solid var(--border,#2b3441);border-radius:12px;padding:13px;background:var(--panel,#111821);min-width:0}.s18-backup__card h3{margin:0 0 8px;font-size:14px}.s18-backup__card p{overflow-wrap:anywhere}.s18-backup__buttons{display:flex;gap:7px;flex-wrap:wrap}.s18-backup button{border:1px solid var(--border,#2b3441);border-radius:9px;background:#182231;color:inherit;padding:8px 10px;cursor:pointer}.s18-backup button:disabled{opacity:.45;cursor:not-allowed}.s18-backup pre{max-width:100%;max-height:300px;overflow:auto;white-space:pre-wrap;word-break:break-word;font-size:11px}.s18-backup__warning{border-inline-start:3px solid #c69245;padding-inline-start:10px}.s18-backup__attempts{max-height:180px;overflow:auto;font-size:11px}@media(max-width:1100px){.s18-backup__flow{grid-template-columns:repeat(3,minmax(0,1fr))}.s18-backup__work{grid-template-columns:minmax(210px,.42fr) minmax(0,1fr)}.s18-backup__work>*:last-child{grid-column:1/-1}}@media(max-width:760px){.s18-backup__flow,.s18-backup__work{grid-template-columns:1fr}.s18-backup__work>*:last-child{grid-column:auto}}
`;

export function mountBackupSurface({stage,registry,workspace,button,adapter}={}){
  if(!stage||!registry||!adapter)throw Error('BACKUP_PRODUCT_COMPOSITION_REQUIRED');
  const exec=(id,fn)=>async()=>{const result=await fn();workspace?.status?.(result?.ok?`${id} completed truthfully`:`${id} unavailable/failed · ${result?.code||'UNKNOWN'}`,result?.ok?'info':'error');render();return result;};
  registry.register('backup.package',adapter.owner,'Create verified BackupPackage',exec('backup.package',()=>adapter.createPackage()));
  registry.register('backup.plan',adapter.owner,'Plan restore drill',exec('backup.plan',()=>adapter.plan()),()=>adapter.availability('backup.plan'));
  registry.register('backup.preview',adapter.owner,'Preview exact package/plan',exec('backup.preview',()=>adapter.preview()),()=>adapter.availability('backup.preview'));
  registry.register('backup.stage',adapter.owner,'Stage isolated drill intent',exec('backup.stage',()=>adapter.stage()),()=>adapter.availability('backup.stage'));
  registry.register('backup.drill',adapter.owner,'Run isolated restore drill',exec('backup.drill',()=>adapter.drill()),()=>adapter.availability('backup.drill'));
  registry.register('backup.activationRequest',adapter.owner,'Request activation authority',exec('backup.activationRequest',()=>adapter.requestActivation()),()=>adapter.availability('backup.activationRequest'));
  const cmd=(id,label)=>typeof button==='function'?button(id,label):`<button type="button" data-command="${safe(id)}">${safe(label)}</button>`;
  const render=()=>{const s=adapter.snapshot(),pkg=s.packages.find(row=>row.packageId===s.selectedPackageId)||s.packages.at(-1)||null,truth=adapter.truth(),steps=[['Plan',s.plan?.state||'NOT_PLANNED'],['Preview',s.preview?.state||'NOT_PREVIEWED'],['Stage',s.stage?.state||'NOT_STAGED'],['Drill',s.lastDrill?.status||'NOT_RUN'],['Activation',s.lastActivation?.status||'NOT_REQUESTED']];stage.innerHTML=`<section class="s18-backup" data-w05-surface="backup" data-domain-owner="${safe(adapter.owner)}"><style>${STYLE}</style><header class="s18-backup__banner"><h2>Recovery Safety Workbench</h2><p>Package → plan → preview → stage → isolated drill → activation request. <bdi dir="ltr">STAGED_AND_VERIFIED != LIVE_RESTORED</bdi>.</p><p class="s18-backup__warning">No command on this surface owns a production restore endpoint. Persistence ownership remains unchanged.</p></header><div class="s18-backup__flow">${steps.map(([label,state])=>`<article class="s18-backup__step"><h3>${safe(label)}</h3><p dir="ltr">${safe(state)}</p></article>`).join('')}</div><div class="s18-backup__work"><article class="s18-backup__card"><h3>BackupPackage</h3><div class="s18-backup__buttons">${cmd('backup.package','Create verified package')}</div><p dir="ltr">${safe(pkg?.packageId||'No package selected')}</p><p><bdi dir="ltr">${safe(pkg?.manifestSha256||'manifest SHA pending')}</bdi></p></article><article class="s18-backup__card"><h3>Recovery lifecycle</h3><div class="s18-backup__buttons">${cmd('backup.plan','Plan')}${cmd('backup.preview','Preview')}${cmd('backup.stage','Stage')}${cmd('backup.drill','Drill')}${cmd('backup.activationRequest','Request activation')}</div><pre dir="ltr">${safe(JSON.stringify(s.lastActivation||s.lastDrill||s.stage||s.preview||s.plan||{state:'IDLE'},null,2))}</pre></article><article class="s18-backup__card"><h3>Provider truth</h3><p><bdi dir="ltr">liveRestored: ${safe(String(truth.drillLiveRestored))}</bdi></p><p><bdi dir="ltr">productionDatabaseMutated: ${safe(String(truth.productionDatabaseMutated))}</bdi></p><p><bdi dir="ltr">activation: ${safe(truth.activationAuthority)}</bdi></p><p class="s18-backup__warning">Durable failed-attempt/compensation journal: <bdi dir="ltr">${safe(truth.durableFailureCompensationHistory)}</bdi></p></article></div><article class="s18-backup__card"><h3>Attempt history — current UI session</h3><div class="s18-backup__attempts">${s.attemptHistory.length?s.attemptHistory.slice().reverse().map(row=>`<p><bdi dir="ltr">${safe(row.attemptId)} · ${safe(row.operation)} · ${safe(row.status)}</bdi></p>`).join(''):'<p>No attempts yet.</p>'}</div></article></section>`;
    const cards=[...stage.querySelectorAll('.s18-backup__work > .s18-backup__card')],history=stage.querySelector('.s18-backup > .s18-backup__card:last-child');
    if(cards[0])workspace?.region?.('LEFT',{node:cards[0],label:'BackupPackage'});
    if(cards[2])workspace?.region?.('RIGHT',{node:cards[2],label:'Provider truth'});
    if(history)workspace?.region?.('BOTTOM',{node:history,label:'Backup attempt history',summary:'Current UI-session attempt history; durable failure journal truth remains provider-owned.'});
    workspace?.refreshToolbar?.();
  };
  stage.dataset.surfaceComposition='backup-recovery-safety-workbench';render();workspace?.toolbar?.(['backup.package',...BACKUP_COMMANDS,'foundation.settings']);
  return Object.freeze({owner:'RecoverySafetyWorkbench',render,adapter,slots:{CENTER:'RecoverySafetyWorkbench',LEFT:'typed-package-projection-pending-shared-region-wiring',RIGHT:'typed-package-context-pending-shared-region-wiring',BOTTOM:'shared-bottom-shell/domain-projection'}});
}
